function renderLibraries(items) {
  const host = document.querySelector("#library-results");
  host.replaceChildren();
  for (const r of items) {
    const card = document.createElement("article");
    const title = document.createElement("h3"); title.textContent = r.name;
    const address = document.createElement("p"); address.textContent = r.address;
    const date = document.createElement("small"); date.textContent = `기준일 ${r.referenceDate}`;
    card.append(title, address, date); host.append(card);
  }
  document.querySelector("#result-count").textContent = items.length ? `${items.length}개 도서관` : "결과가 없습니다. 조건을 바꿔보세요.";
}

type Query = { q: string; district: string };
// loadLibraries(): Promise<Library[]>
// 읽기/형식 오류는 reject합니다.
// searchLibraries(rows, query): Library[]
// 빈 query는 전체, 결과 없음은 []입니다.
// 원본 rows를 변경하지 않습니다.
// renderLibraries(rows): 화면만 갱신합니다.

async function loadLibraries(url = null) {
  let data;
  if (url) {
    const r = await fetch(url); if (!r.ok) throw new Error(`HTTP ${r.status}`);
    data = await r.json();
  } else data = JSON.parse(document.querySelector("#library-data").textContent);
  if (!Array.isArray(data.rows)) throw new Error("rows 필요");
  return data.rows.map(row => ({
    ...row,
    district: String(row.address ?? "").match(/(기흥구|수지구|처인구)/)?.[1] ?? "기타"
  }));
}

function searchLibraries(rows, { q = "", district = "" } = {}) {
  const term = q.trim().toLowerCase();
  return rows.filter(r => {
    const text = `${r.name} ${r.address}`.toLowerCase();
    const textOK = !term || text.includes(term);
    const districtOK = !district || r.district === district;
    return textOK && districtOK;
  });
}

const rows = await loadLibraries();
const names = q => searchLibraries(rows, q).map(r => r.name);
console.log(names({ q: " 포곡 " }));
// ["포곡도서관"]
console.log(names({ q: "포곡", district: "기흥구" }));
// []
console.log(names({ district: "기흥구" }).length);
// 9

const a = searchLibraries(rows, { q: " 포곡 " });
console.assert(a.length === 1 && a[0].name === "포곡도서관",
  "공백을 제거한 이름 검색");
const b = searchLibraries(rows, { district: "기흥구" });
console.assert(b.length === 9 && b.every(r => r.district === "기흥구"),
